private string GetPostedText(TextBox txtValue)
{
    if (txtValue == null)
        return string.Empty;

    if (Page != null && Page.Request != null && Page.Request.Form != null)
    {
        string postedValue = Page.Request.Form[txtValue.UniqueID];
        if (postedValue != null)
            return postedValue.Trim();

        postedValue = Page.Request.Form[txtValue.ClientID];
        if (postedValue != null)
            return postedValue.Trim();

        string normalizedClientID = txtValue.ClientID;
        string answerPrefix = this.ClientID;
        foreach (string key in Page.Request.Form.AllKeys)
        {
            if (string.IsNullOrEmpty(key))
                continue;

            string normalizedKey = key.Replace('$', '_');
            if (normalizedKey == normalizedClientID)
                return Page.Request.Form[key].Trim();

            if (key.IndexOf(answerPrefix, StringComparison.Ordinal) >= 0
                && key.IndexOf("txtValue", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                postedValue = Page.Request.Form[key];
                if (postedValue != null && postedValue.Trim() != string.Empty)
                    return postedValue.Trim();
            }
        }
    }

    return txtValue.Text.Trim();
}

public void ApplyPostedValues()
{
    if (Page == null || !Page.IsPostBack)
        return;

    foreach (RepeaterItem item in rptList.Items)
    {
        if (item.ItemType != ListItemType.Item && item.ItemType != ListItemType.AlternatingItem)
            continue;

        TextBox txtValue = item.FindControl("txtValue") as TextBox;
        if (txtValue == null)
            continue;

        string postedText = GetPostedText(txtValue);
        if (postedText != string.Empty)
        {
            txtValue.ReadOnly = false;
            txtValue.Text = postedText;
        }
    }
}

