private DataRow GetSavedDetailRow(int questionId)
{
    if (this.dtbSavedDetail == null)
        return null;

    DataRow latestRow = null;
    long latestDoneDetailId = 0;

    foreach (DataRow dr in this.dtbSavedDetail.Rows)
    {
        if (dr["QuestionID"] == DBNull.Value)
            continue;

        if (Convert.ToInt32(dr["QuestionID"]) != questionId)
            continue;

        long doneDetailId = 0;
        if (dr.Table.Columns.Contains("DoneDetailID") && dr["DoneDetailID"] != DBNull.Value)
            doneDetailId = Convert.ToInt64(dr["DoneDetailID"]);

        if (latestRow == null || doneDetailId >= latestDoneDetailId)
        {
            latestRow = dr;
            latestDoneDetailId = doneDetailId;
        }
    }

    return latestRow;
}

