private string GetPostedText(TextBox txtValue)
{
    if (txtValue == null)
        return string.Empty;

    if (Page != null && Page.Request != null && Page.Request.Form != null)
    {
        string postedValue = Page.Request.Form[txtValue.UniqueID];
        if (postedValue != null)
            return postedValue.Trim();

        postedValue = Page.Request.Form[txtValue.ClientID];
        if (postedValue != null)
            return postedValue.Trim();

        string normalizedClientID = txtValue.ClientID;
        foreach (string key in Page.Request.Form.AllKeys)
        {
            if (string.IsNullOrEmpty(key))
                continue;

            string normalizedKey = key.Replace('$', '_');
            if (normalizedKey == normalizedClientID)
                return Page.Request.Form[key].Trim();
        }
    }

    if (Page != null && Page.IsPostBack)
        return string.Empty;

    return txtValue.Text.Trim();
}

