private decimal ParseMark(string markText)
{
    decimal markValue;
    if (decimal.TryParse(
        markText.Replace(',', '.'),
        System.Globalization.NumberStyles.Any,
        System.Globalization.CultureInfo.InvariantCulture,
        out markValue))
    {
        return markValue;
    }

    return 0;
}

private string GetRepeaterRowUniquePrefix(string controlUniqueId)
{
    if (string.IsNullOrEmpty(controlUniqueId))
        return string.Empty;

    int lastDollar = controlUniqueId.LastIndexOf('$');
    if (lastDollar <= 0)
        return controlUniqueId;

    return controlUniqueId.Substring(0, lastDollar + 1);
}

private bool TryGetPostedMarkFromRequest(RepeaterItem item, out decimal mark, out string markText)
{
    mark = 0;
    markText = string.Empty;

    HiddenField hidQuestionID = item.FindControl("hidQuestionID") as HiddenField;
    if (hidQuestionID == null || Page == null || Page.Request == null || Page.Request.Form == null)
        return false;

    string rowUniquePrefix = GetRepeaterRowUniquePrefix(hidQuestionID.UniqueID);
    if (string.IsNullOrEmpty(rowUniquePrefix))
        return false;

    foreach (string key in Page.Request.Form.AllKeys)
    {
        if (string.IsNullOrEmpty(key) || key.IndexOf("txtValue") < 0)
            continue;

        if (key.IndexOf(rowUniquePrefix) != 0)
            continue;

        string value = Page.Request.Form[key];
        if (value == null || value.Trim() == string.Empty)
            continue;

        markText = value.Trim();
        mark = ParseMark(markText);
        return true;
    }

    return false;
}

private int GetQuestionOrderIndex(int questionId, int defaultOrderIndex)
{
    if (this.dtbDataQuestion != null)
    {
        DataRow[] rows = this.dtbDataQuestion.Select("QuestionID = " + questionId.ToString());
        if (rows.Length > 0
            && rows[0].Table.Columns.Contains("OrderIndex")
            && rows[0]["OrderIndex"] != DBNull.Value)
        {
            return Convert.ToInt32(rows[0]["OrderIndex"]);
        }
    }

    DataRow savedRow = GetSavedDetailRow(questionId);
    if (savedRow != null
        && savedRow.Table.Columns.Contains("OrderIndex")
        && savedRow["OrderIndex"] != DBNull.Value)
    {
        return Convert.ToInt32(savedRow["OrderIndex"]);
    }

    return defaultOrderIndex;
}

private void ApplyPostedMarkToDoneDetail(RepeaterItem item, POL_DoneDetail itemDoneDetail, PollPart.Answer uAnswer)
{
    decimal postedMark;
    string postedMarkText;
    if (!TryGetPostedMarkFromRequest(item, out postedMark, out postedMarkText))
        return;

    itemDoneDetail.DoMark = postedMark;
    itemDoneDetail.DoAnswerContent = postedMarkText;

    if (string.IsNullOrEmpty(itemDoneDetail.DoAnswerIndex))
        itemDoneDetail.DoAnswerIndex = ";1;";

    if (uAnswer != null && string.IsNullOrEmpty(itemDoneDetail.DoAnswerID))
    {
        POL_DoneDetail tempDetail = new POL_DoneDetail();
        uAnswer.GetInfo(tempDetail);
        if (!string.IsNullOrEmpty(tempDetail.DoAnswerID))
            itemDoneDetail.DoAnswerID = tempDetail.DoAnswerID;
    }

    if (string.IsNullOrEmpty(itemDoneDetail.DoAnswerID) && this.dtbDataAnswer != null)
    {
        HiddenField hidQuestionID = item.FindControl("hidQuestionID") as HiddenField;
        if (hidQuestionID != null)
        {
            DataRow[] answerRows = this.dtbDataAnswer.Select("QuestionID = " + hidQuestionID.Value);
            if (answerRows.Length > 0 && answerRows[0].Table.Columns.Contains("AnswerID"))
                itemDoneDetail.DoAnswerID = ";" + answerRows[0]["AnswerID"].ToString() + ";";
        }
    }
}

