private Dictionary<int, decimal> BackupReviewMarksByQuestion()
{
    Dictionary<int, decimal> reviewMarks = new Dictionary<int, decimal>();

    if (this.dtbSavedDetail == null && this.DoneID != null)
        this.dtbSavedDetail = GetSavedDetailData(this.DoneID.Value);

    if (this.dtbSavedDetail == null)
        return reviewMarks;

    foreach (DataRow dr in this.dtbSavedDetail.Rows)
    {
        if (dr["QuestionID"] == DBNull.Value)
            continue;

        if (!dr.Table.Columns.Contains("ReviewMark") || dr["ReviewMark"] == DBNull.Value)
            continue;

        string reviewMarkText = dr["ReviewMark"].ToString().Trim();
        if (reviewMarkText == string.Empty)
            continue;

        int questionId = Convert.ToInt32(dr["QuestionID"]);
        reviewMarks[questionId] = Convert.ToDecimal(dr["ReviewMark"]);
    }

