private string GetRepeaterRowUniquePrefix(string controlUniqueId)
{
    if (string.IsNullOrEmpty(controlUniqueId))
        return string.Empty;

    int lastDollar = controlUniqueId.LastIndexOf('$');
    if (lastDollar <= 0)
        return controlUniqueId;

    return controlUniqueId.Substring(0, lastDollar + 1);
}

private bool TryGetPostedMarkFromRequest(RepeaterItem item, out decimal mark, out string markText)
{
    mark = 0;
    markText = string.Empty;

    HiddenField hidQuestionID = item.FindControl("hidQuestionID") as HiddenField;
    if (hidQuestionID == null || Page == null || Page.Request == null || Page.Request.Form == null)
        return false;

    string rowUniquePrefix = GetRepeaterRowUniquePrefix(hidQuestionID.UniqueID);
    if (string.IsNullOrEmpty(rowUniquePrefix))
        return false;

    foreach (string key in Page.Request.Form.AllKeys)
    {
        if (string.IsNullOrEmpty(key) || key.IndexOf("txtValue") < 0)
            continue;

        if (key.IndexOf(rowUniquePrefix) != 0)
            continue;

        string value = Page.Request.Form[key];
        if (value == null || value.Trim() == string.Empty)
            continue;

        markText = value.Trim();
        mark = ParseMark(markText);
        return true;
    }

    return false;
}

