private class PostedMarkInfo
{
    public decimal Mark;
    public string MarkText;
}

private HashSet<int> BuildValidQuestionIdSet()
{
    HashSet<int> ids = new HashSet<int>();
    if (this.dtbDataQuestion == null)
        return ids;

    foreach (DataRow dr in this.dtbDataQuestion.Rows)
    {
        if (dr["QuestionID"] == DBNull.Value)
            continue;

        ids.Add(Convert.ToInt32(dr["QuestionID"]));
    }

    return ids;
}

private string FindPostedTxtValueByRowPrefix(string[] allKeys, string rowPrefix)
{
    if (string.IsNullOrEmpty(rowPrefix) || allKeys == null)
        return string.Empty;

    string lastValue = string.Empty;
    foreach (string key in allKeys)
    {
        if (string.IsNullOrEmpty(key) || key.IndexOf("txtValue") < 0)
            continue;

        if (key.Length < rowPrefix.Length || key.IndexOf(rowPrefix) != 0)
            continue;

        string value = Page.Request.Form[key];
        if (value != null && value.Trim() != string.Empty)
            lastValue = value.Trim();
    }

    return lastValue;
}

private Dictionary<int, PostedMarkInfo> CollectPostedMarksFromForm()
{
    Dictionary<int, PostedMarkInfo> result = new Dictionary<int, PostedMarkInfo>();
    if (Page == null || Page.Request == null || Page.Request.Form == null)
        return result;

    string[] allKeys = Page.Request.Form.AllKeys;
    if (allKeys == null)
        return result;

    HashSet<int> validQuestionIds = BuildValidQuestionIdSet();

    foreach (string key in allKeys)
    {
        if (string.IsNullOrEmpty(key))
            continue;

        int hidIndex = key.LastIndexOf("hidQuestionID");
        if (hidIndex < 0)
            continue;

        string questionIdText = Page.Request.Form[key];
        if (string.IsNullOrEmpty(questionIdText))
            continue;

        int questionId = 0;
        if (!int.TryParse(questionIdText, out questionId))
            continue;

        if (validQuestionIds.Count > 0 && !validQuestionIds.Contains(questionId))
            continue;

        string rowPrefix = key.Substring(0, hidIndex);
        string markText = FindPostedTxtValueByRowPrefix(allKeys, rowPrefix);
        if (string.IsNullOrEmpty(markText))
            continue;

        PostedMarkInfo info = new PostedMarkInfo();
        info.MarkText = markText;
        info.Mark = ParseMark(markText);
        result[questionId] = info;
    }

    return result;
}

private void FillAnswerIdFromDataTable(POL_DoneDetail itemDoneDetail, int questionId)
