    DataRow[] answerRows = this.dtbDataAnswer.Select("QuestionID = " + questionId.ToString());
    if (answerRows.Length > 0 && answerRows[0].Table.Columns.Contains("AnswerID"))
        itemDoneDetail.DoAnswerID = ";" + answerRows[0]["AnswerID"].ToString() + ";";
}

private void ApplyPostedMarkFromDictionary(
    POL_DoneDetail itemDoneDetail,
    int questionId,
    Dictionary<int, PostedMarkInfo> postedMarks)
{
    if (postedMarks == null)
        return;

    PostedMarkInfo postedInfo;
    if (!postedMarks.TryGetValue(questionId, out postedInfo))
        return;

    itemDoneDetail.DoMark = postedInfo.Mark;
    itemDoneDetail.DoAnswerContent = postedInfo.MarkText;

    if (string.IsNullOrEmpty(itemDoneDetail.DoAnswerIndex))
        itemDoneDetail.DoAnswerIndex = ";1;";

    if (string.IsNullOrEmpty(itemDoneDetail.DoAnswerID))
        FillAnswerIdFromDataTable(itemDoneDetail, questionId);
}

