private Dictionary<int, decimal> BackupTeacherReviewMarks(long doneId, DCore.IData objIDB)
{
    Dictionary<int, decimal> reviewMarks = new Dictionary<int, decimal>();
    DataTable dtbDetail = GetSavedDetailData(doneId, objIDB);
    if (dtbDetail == null)
        return reviewMarks;

    foreach (DataRow dr in dtbDetail.Rows)
    {
        if (dr["QuestionID"] == DBNull.Value)
            continue;

        if (!dtbDetail.Columns.Contains("ReviewMark") || dr["ReviewMark"] == DBNull.Value)
            continue;

        string reviewText = dr["ReviewMark"].ToString().Trim();
        if (reviewText == string.Empty)
            continue;

        int questionId = Convert.ToInt32(dr["QuestionID"]);
        reviewMarks[questionId] = Convert.ToDecimal(dr["ReviewMark"]);
    }

    return reviewMarks;
}

private bool DeleteDoneDetailsByDoneId(long doneId, DCore.IData objIDB)
