    {
        MsgBox.ShowError("Không xóa được chi tiết phiếu cũ!<br>" + ex.Message);
        return false;
    }
}

private bool RestoreTeacherReviewMarks(long doneId, Dictionary<int, decimal> reviewMarks, DCore.IData objIDB)
{
    if (reviewMarks == null || reviewMarks.Count == 0)
        return true;

    try
    {
        POL_DoneDetail obj = new POL_DoneDetail();
        if (objIDB != null)
            obj.IDB = objIDB;

        foreach (KeyValuePair<int, decimal> item in reviewMarks)
        {
            obj.GetDataTable(
                "POL_DoneDetail_UpdateReviewMarkByDoneQuestion",
                "@DoneID", doneId,
                "@QuestionID", item.Key,
                "@ReviewMark", item.Value);
        }

        return true;
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Không khôi phục được điểm giáo viên chấm!<br>" + ex.Message);
        return false;
    }
}

